"""F-symbols of su(2)_k (quantum 6j symbols) and known data of small fusion categories.

su(2)_k: labels j = 0, 1/2, ..., k/2 (we use l = 2j), q = exp(i pi/(k+2)), quantum integers
[x] = sin(pi x/(k+2)) / sin(pi/(k+2)).  The unitary F-move
    F^{abc}_d[e,f] : ((a b)_e c)_d -> (a (b c)_f)_d
is (-1)^{a+b+c+d} sqrt([2e+1][2f+1]) {a b e; c d f}_q with the Racah/Kirillov-Reshetikhin
q-6j symbol.  ``pentagon_check`` verifies the pentagon equation numerically, so the
conventions are tested, not assumed.

Anomalies (literature, quoted):
* a Z_N generated by a simple current J of spin h_J has trivial F-symbols (can be gauged,
  is anomaly free as a fusion category) iff N h_J in Z; for several currents the condition is
  N_a h_a in Z on a basis of independent generators (the quadratic form then comes from a
  bicharacter).
* a fusion category can be gauged as a whole (has a fiber functor) only if all quantum
  dimensions are integers.  Fib, Ising, and su(2)_k for k >= 2 cannot.
* Tambara-Yamagami TY(A, chi, tau) has a fiber functor only if |A| is a perfect square and A has a
  Lagrangian subgroup for chi (Tambara 2000); TY(A) is group-theoretical iff such a Lagrangian
  subgroup exists (Gelaki-Naidu-Nikshych 2009).
* algebra objects of su(2)_k (ADE, Kirillov-Ostrik 2002): A_k always; D-type 1 + L_k for k even
  (commutative iff k = 0 mod 4); E6 at k = 10 (1 + L_6), E7 at k = 16 (1 + L_8 + L_16),
  E8 at k = 28 (1 + L_10 + L_18 + L_28).
"""

from __future__ import annotations

import math
import random
from functools import lru_cache
from typing import Dict, List, Optional, Tuple


class SU2k:
    def __init__(self, k: int):
        self.k = k
        self.n = k + 2

    def qint(self, x: int) -> float:
        return math.sin(math.pi * x / self.n) / math.sin(math.pi / self.n)

    @lru_cache(maxsize=None)
    def qfact(self, x: int) -> float:
        if x < 0:
            raise ValueError
        p = 1.0
        for i in range(1, x + 1):
            p *= self.qint(i)
        return p

    def adm(self, a: int, b: int, c: int) -> bool:
        """Admissible triple in doubled units (l = 2j)."""
        return (a + b + c) % 2 == 0 and abs(a - b) <= c <= a + b and a + b + c <= 2 * self.k

    def _delta(self, a, b, c):
        # labels in doubled units; j-sums: (a+b-c)/2 etc.
        f = self.qfact
        return math.sqrt(f((a + b - c) // 2) * f((a - b + c) // 2) * f((-a + b + c) // 2) / f((a + b + c) // 2 + 1))

    def sixj(self, a, b, e, c, d, f) -> float:
        """q-6j symbol {a b e; c d f} (doubled labels), triangles (a b e), (a d f), (c b f), (c d e)."""
        if not (self.adm(a, b, e) and self.adm(a, d, f) and self.adm(c, b, f) and self.adm(c, d, e)):
            return 0.0
        t1 = (a + b + e) // 2
        t2 = (a + d + f) // 2
        t3 = (c + b + f) // 2
        t4 = (c + d + e) // 2
        p1 = (a + b + c + d) // 2
        p2 = (b + e + d + f) // 2
        p3 = (e + a + f + c) // 2
        s = 0.0
        F = self.qfact
        for z in range(max(t1, t2, t3, t4), min(p1, p2, p3) + 1):
            s += (-1) ** z * F(z + 1) / (F(z - t1) * F(z - t2) * F(z - t3) * F(z - t4) *
                                         F(p1 - z) * F(p2 - z) * F(p3 - z))
        return self._delta(a, b, e) * self._delta(a, d, f) * self._delta(c, b, f) * self._delta(c, d, e) * s

    def F(self, a, b, c, d, e, f) -> float:
        """F^{abc}_d[e,f] (doubled labels)."""
        if not (self.adm(a, b, e) and self.adm(e, c, d) and self.adm(b, c, f) and self.adm(a, f, d)):
            return 0.0
        sign = (-1) ** ((a + b + c + d) // 2)
        return sign * math.sqrt(self.qint(e + 1) * self.qint(f + 1)) * self.sixj(a, b, e, c, d, f)

    def fuse(self, a, b):
        return [c for c in range(abs(a - b), min(a + b, 2 * self.k - a - b) + 1, 2)]

    def pentagon_check(self, samples: int = 300, seed: int = 0) -> float:
        """max |pentagon violation| over random admissible configurations (or all, if few)."""
        rnd = random.Random(seed)
        L = list(range(self.k + 1))
        worst = 0.0
        configs = []
        for _ in range(samples):
            a, b, c, d = (rnd.choice(L) for _ in range(4))
            # outer label e: any in fusion of a b c d
            es = set()
            for x in self.fuse(a, b):
                for y in self.fuse(x, c):
                    es.update(self.fuse(y, d))
            if not es:
                continue
            e = rnd.choice(sorted(es))
            configs.append((a, b, c, d, e))
        for a, b, c, d, e in configs:
            # (((a b)_p c)_q d)_e  -> (a (b (c d)_r)_s)_e
            for p in self.fuse(a, b):
                for q in self.fuse(p, c):
                    if e not in self.fuse(q, d):
                        continue
                    for r in self.fuse(c, d):
                        for s in self.fuse(b, r):
                            if e not in self.fuse(a, s):
                                continue
                            lhs = self.F(p, c, d, e, q, r) * self.F(a, b, r, e, p, s)
                            rhs = 0.0
                            for t in self.fuse(b, c):
                                rhs += self.F(a, b, c, q, p, t) * self.F(a, t, d, e, q, s) * self.F(b, c, d, s, t, r)
                            worst = max(worst, abs(lhs - rhs))
        return worst

    def fs_indicator(self, a: int) -> int:
        """Frobenius-Schur indicator of the self-dual label a: d_a F^{a a a}_a[0,0]-type sign."""
        if 2 * a > 2 * self.k:
            raise ValueError
        v = self.qint(a + 1) * self.F(a, a, a, a, 0, 0)
        return int(round(v))


def fib_from_su2_3() -> List[List[float]]:
    """F^{tau tau tau}_tau of Fib, taken from su(2)_3 with tau = l = 2."""
    S = SU2k(3)
    return [[S.F(2, 2, 2, 2, e, f) for f in (0, 2)] for e in (0, 2)]


def known_category(k: int) -> str:
    """Name of the line category of one N=2 minimal-model factor at level k (su(2)_k part)."""
    if k == 0:
        return "trivial (c = 0 factor)"
    if k == 1:
        return "su(2)_1: all lines invertible (Z2, spin 1/4: anomalous)"
    if k == 2:
        return "su(2)_2 = Ising: sigma (d = sqrt 2) and the Z2 line eps; TY(Z2)"
    if k == 3:
        return "su(2)_3 = Fib x (Z2 with spin 3/4); Fibonacci line tau = l=2 (d = golden ratio)"
    if k == 4:
        return "su(2)_4: even part {0,2,4} has the fusion ring of Rep(S3); odd lines d = sqrt 3"
    if k % 2:
        return f"su(2)_{k} = (even part, SO(3)_{k}) x (Z2 with spin {k}/4)"
    return f"su(2)_{k} (Z2 simple current with spin {k}/4)"


def algebra_objects(k: int) -> List[str]:
    out = []
    if k % 2 == 0 and k > 0:
        out.append(f"D-type 1 + L_{k} (Z2 gauging; {'commutative' if k % 4 == 0 else 'not commutative'})")
    ex = {10: "E6: 1 + L_6", 16: "E7: 1 + L_8 + L_16", 28: "E8: 1 + L_10 + L_18 + L_28"}
    if k in ex:
        out.append(ex[k] + " (non-invertible gauging, exceptional modular invariant)")
    return out


def pointed_anomaly(orders: List[int], spins) -> List[bool]:
    """Per independent generator: True if N h in Z (trivial F-symbols)."""
    return [((N * h) % 1) == 0 for N, h in zip(orders, spins)]
